import Foundation

// Contracts between modules. Each module implements the type named in the comment, in its own
// folder. Do not edit this file from a module — report a needed change instead.

// MARK: - Storage layout

/// All user files live in ~/Library/Application Support/Runespeak/.
public struct AppPaths: Sendable {
    public let root: URL
    public init(root: URL) { self.root = root }

    public static var `default`: AppPaths {
        let base = FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask)[0]
        return AppPaths(root: base.appendingPathComponent("Runespeak", isDirectory: true))
    }

    /// Dictionary files shipped with the app and refreshed from its bundle at launch
    /// (official_names / abbreviations / chat_commands `.classic.tsv` and `.retail.tsv`, nicknames.tsv).
    public var dataDirectory: URL { root.appendingPathComponent("data", isDirectory: true) }
    public var settingsFile: URL { root.appendingPathComponent("settings.json") }
    public var chatAreaFile: URL { root.appendingPathComponent("chat_area.json") }
    /// The Claude key. Plain text, permissions 0600. Same as `keyFile(for: .claude)`.
    public var keyFile: URL { keyFile(for: .claude) }
    /// One key file per provider, plain text, permissions 0600.
    public func keyFile(for provider: AIProvider) -> URL {
        switch provider {
        case .claude: return root.appendingPathComponent("key_claude.txt")
        case .openai: return root.appendingPathComponent("key_openai.txt")
        case .gemini: return root.appendingPathComponent("key_gemini.txt")
        }
    }
    public var chatHistoryFile: URL { root.appendingPathComponent("chat_history.txt") }
    /// Corrections made with "다시 번역". Tab-separated: source, translation, note.
    public var correctionsFile: URL { root.appendingPathComponent("corrections.tsv") }
    /// The user's own names. Tab-separated like nicknames.tsv: korean, english, aliases.
    public var myTermsFile: URL { root.appendingPathComponent("my_terms.tsv") }
    public var tokenUsageFile: URL { root.appendingPathComponent("token_usage.json") }
    public var errorsFile: URL { root.appendingPathComponent("errors.log") }

    public func ensureDirectories() throws {
        try FileManager.default.createDirectory(at: dataDirectory, withIntermediateDirectories: true)
    }
}

// MARK: - Glossary  (implemented in Glossary/ as `final class GlossaryStore: GlossaryProviding`)
//
//   public init(paths: AppPaths, flavor: GameFlavor)   // loads synchronously; missing files are fine
//
// Priority when the same name appears twice: my_terms.tsv > nicknames.tsv > official_names.<flavor>.tsv.

public struct GlossaryPair: Sendable, Hashable {
    public var korean: String
    public var english: String
    public init(korean: String, english: String) { self.korean = korean; self.english = english }
}

public struct CorrectionExample: Sendable, Hashable {
    public var source: String
    public var translation: String
    public var note: String?
    public init(source: String, translation: String, note: String?) {
        self.source = source; self.translation = translation; self.note = note
    }
}

/// One sense of an abbreviation or slang token, from abbreviations.<flavor>.tsv.
public struct GlossaryAbbreviation: Sendable, Hashable {
    /// The token as the table spells it: "DM".
    public var abbr: String
    /// What it stands for: an official English name, or a plain description. May be empty.
    public var english: String
    /// The official Korean name, or how Korean players say it. Empty when there is no settled term.
    public var korean: String
    /// When this sense applies. May be empty.
    public var note: String
    public init(abbr: String, english: String = "", korean: String = "", note: String = "") {
        self.abbr = abbr; self.english = english; self.korean = korean; self.note = note
    }
}

/// Dictionary material relevant to ONE piece of chat text, to be put in the translation prompt.
public struct GlossaryHints: Sendable, Equatable {
    /// Official names found in the text (either language) with their counterpart. Either side
    /// may carry the nickname that matched, after a bar: "Undercity | UC".
    public var names: [GlossaryPair] = []
    /// Abbreviation candidates found in the text, one entry per sense.
    public var abbreviations: [GlossaryAbbreviation] = []
    /// Official names that are just as often an ordinary word (one-word spells and
    /// specializations, one-word Korean item names): the context decides whether the name is meant.
    public var looseNames: [GlossaryPair] = []
    /// Earlier corrected translations of the same or similar text.
    public var corrections: [CorrectionExample] = []
    public init() {}
    public var isEmpty: Bool { names.isEmpty && abbreviations.isEmpty && looseNames.isEmpty && corrections.isEmpty }
}

public struct OutgoingCommand: Sendable, Equatable {
    /// English slash command to send, e.g. "/s", "/g", "/w Name". nil when the text had no chat command.
    public var command: String?
    /// The part that should be translated.
    public var text: String
    public init(command: String?, text: String) { self.command = command; self.text = text }
}

public protocol GlossaryProviding: AnyObject, Sendable {
    /// Number of loaded name pairs (for the status line; 0 means the data files are missing).
    var entryCount: Int { get }
    /// Number of loaded abbreviation senses (for the status line).
    var abbreviationCount: Int { get }
    /// Dictionary material for a batch of texts. Must be fast (called for every chat line): < 5 ms per line.
    func hints(for texts: [String]) -> GlossaryHints
    /// Splits "/파티 잠시만요" into command "/p" + text "잠시만요" using chat_commands.<flavor>.tsv. Whisper-style commands
    /// keep their target: "/ㅈ Thrall 잠시만요" → command "/w Thrall", text "잠시만요".
    /// A slash command that is not chat ("/roll 100") comes back whole in `command` with empty
    /// `text`: there is nothing to translate.
    func parseOutgoing(_ input: String) -> OutgoingCommand
    /// Appends to corrections.tsv and makes it available to later `hints` calls.
    func addCorrection(_ example: CorrectionExample)
    /// Re-reads every file (the game flavor changed).
    func reload(flavor: GameFlavor)
}

public extension GlossaryProviding {
    var abbreviationCount: Int { 0 }
}

// MARK: - Chat tracking  (implemented in Chat/ as `final class ChatTracker: ChatTracking`)
//
//   public init(clientLocale: ClientLocale)
//
// Turns successive OCR frames of a scrolling chat window into a stream of NEW messages:
// merges wrapped lines, parses channel/sender, and never reports the same message twice even
// though it stays on screen for many frames and OCR output jitters slightly between frames.

public protocol ChatTracking: AnyObject {
    /// Returns messages that appeared since the previous frame, oldest first.
    /// A message whose last line may still be growing (bottom of the window) may be held back one frame.
    func ingest(_ frame: OCRFrame, now: Date) -> [ChatMessage]
    /// Forget everything (region changed, game restarted).
    func reset()
}

public enum LanguageGate {
    // Implemented in Chat/LanguageGate.swift as an extension:
    //   static func needsTranslation(_ text: String, reader: ReaderLanguage) -> Bool
    // reader == .korean: true when the text contains meaningful non-Korean language content
    //   (pure numbers, item links, emoticons, "gg", "ㅋㅋ" → false).
    // reader == .english: true for Korean/Chinese/Japanese/Russian text.
}

