public struct TranslationOutput: Sendable, Equatable {
    public var text: String
    public var note: String?
    public init(text: String, note: String? = nil) { self.text = text; self.note = note }
}

public struct TranslationRequestContext: Sendable {
    public var reader: ReaderLanguage
    public var flavor: GameFlavor
    /// Model id of the translator's provider ("claude-haiku-5-5", "gpt-6-luna", "gemini-3.5-flash-lite"),
    /// normally `AppSettings.modelID()` / `retranslateModelID()`. Any id the user's key can use works.
    public var model: String
    /// A few preceding chat lines (already shown), oldest first, for context. May be empty.
    public var recent: [ChatMessage]
    public init(reader: ReaderLanguage, flavor: GameFlavor, model: String, recent: [ChatMessage] = []) {
        self.reader = reader; self.flavor = flavor; self.model = model; self.recent = recent
    }
    /// Claude tier shorthand.
    public init(reader: ReaderLanguage, flavor: GameFlavor, model: ModelChoice, recent: [ChatMessage] = []) {
        self.init(reader: reader, flavor: flavor, model: model.modelID, recent: recent)
    }
}

public enum TranslationError: Error, Sendable, Equatable {
    case missingAPIKey
    case invalidAPIKey
    case insufficientCredit
    case rateLimited
    case dailyLimitReached      // MyMemory quota
    /// The provider does not know the model id, or this key may not use it. Carries the id.
    case modelNotFound(String)
    case network(String)
    /// No answer within the request's time limit. Kept apart from `network`: the provider may
    /// still finish and bill the generation, so it is not simply sent again.
    case timedOut
    case badResponse(String)
    /// The model or a safety filter declined the request as a whole (one line can cause it).
    case refused
    /// A 200 answer that holds no usable translation (cut off, not in the agreed format).
    case unusableReply(String)

    /// Short Korean text for the UI, not naming a provider.
    public var userMessage: String { userMessage(for: nil) }

    /// Short Korean text for the UI. With a provider the key and billing messages name it
    /// ("ChatGPT API 키가 올바르지 않습니다").
    public func userMessage(for provider: AIProvider?) -> String {
        let name = provider.map { $0.shortName + " " } ?? ""
        switch self {
        case .missingAPIKey: return "\(name)API 키가 없습니다"
        case .invalidAPIKey: return "\(name)API 키가 올바르지 않습니다"
        case .insufficientCredit:
            // Prepaid balance (Anthropic, OpenAI, Google) and exhausted quotas (Gemini free tier,
            // OpenAI spend limits) arrive as the same class of error.
            return provider.map { "\($0.companyName) 계정의 잔액 또는 사용 한도가 부족합니다" } ?? "API 잔액 또는 사용 한도가 부족합니다"
        case .rateLimited: return "요청이 너무 많습니다. 잠시 후 다시 시도합니다"
        case .dailyLimitReached: return "무료 번역의 하루 한도를 다 썼습니다"
        case .modelNotFound(let id): return "모델 '\(id)'을(를) 쓸 수 없습니다. 설정에서 다른 모델을 골라 주세요"
        case .network(let m): return "인터넷 연결 오류: \(m)"
        case .timedOut:
            return provider == nil ? "응답 시간 초과" : "응답이 너무 늦습니다. 설정에서 더 빠른 번역 모델을 골라 보세요"
        case .badResponse(let m), .unusableReply(let m): return "번역 응답 오류: \(m)"
        case .refused: return "모델이 이 내용의 번역을 거절했습니다"
        }
    }
}

public protocol Translating: AnyObject, Sendable {
    /// "Haiku", "GPT-6 Luna", "Gemini 3.5 Flash-Lite", "MyMemory" — shown next to a translation.
    func engineName(for context: TranslationRequestContext) -> String
    /// Translates chat lines in one request. Result is keyed by message id; a message missing from
    /// the result is treated as failed. Throws only when the whole request failed.
    func translateIncoming(_ messages: [ChatMessage], context: TranslationRequestContext) async throws -> [UUID: TranslationOutput]
    /// Careful single-line retranslation with a larger model; returns a note explaining the meaning.
    func retranslate(_ message: ChatMessage, previous: String?, context: TranslationRequestContext) async throws -> TranslationOutput
    /// Translates what the user typed into `language` (an English language name), keeping WoW jargon natural.
    /// Slash commands are NOT handled here — the caller splits them off with GlossaryProviding.parseOutgoing.
    func translateOutgoing(_ text: String, to language: String, context: TranslationRequestContext) async throws -> String
}

public protocol UsageTracking: AnyObject, Sendable {
    /// Record one API response's token counts. The four counts do not overlap: `inputTokens` is
    /// input billed at the full rate, `cacheReadTokens` input served from the provider's prompt
    /// cache, `cacheWriteTokens` input billed at the cache-write rate; `outputTokens` includes
    /// reasoning/thinking tokens.
    func record(provider: AIProvider, modelID: String, inputTokens: Int, outputTokens: Int, cacheReadTokens: Int, cacheWriteTokens: Int)
    /// Estimated spend today in KRW (models with a known price only).
    var todayKRW: Double { get }
    /// Estimated spend since the file was created, in KRW (models with a known price only).
    var totalKRW: Double { get }
    /// True when today's usage includes a model that is not in the price table, so `todayKRW`
    /// is too low — show "일부 모델 단가 미상".
    var todayHasUnknownCost: Bool { get }
    /// Same for `totalKRW`.
    var totalHasUnknownCost: Bool { get }
}

public extension UsageTracking {
    var todayHasUnknownCost: Bool { false }
    var totalHasUnknownCost: Bool { false }
    /// Claude tier shorthand.
    func record(model: ModelChoice, inputTokens: Int, outputTokens: Int, cacheReadTokens: Int, cacheWriteTokens: Int) {
        record(provider: .claude, modelID: model.modelID, inputTokens: inputTokens, outputTokens: outputTokens,
               cacheReadTokens: cacheReadTokens, cacheWriteTokens: cacheWriteTokens)
    }
}
